function openJournal(chunks) {
  let iterator = null;
  let iteratorStarted = false;
  let closed = false;
  let eof = false;
  let returned = false;
  let line = 1;
  let buffer = "";
  let decoder = new TextDecoder("utf-8");
  let pendingNext = null;

  async function acquireIterator() {
    if (!iteratorStarted) {
      iteratorStarted = true;
      iterator = chunks[Symbol.asyncIterator]();
    }
    return iterator;
  }

  async function returnIterator() {
    if (returned || !iterator || typeof iterator.return !== "function") {
      return;
    }
    returned = true;
    await iterator.return();
  }

  async function returnIteratorIgnoringErrors() {
    try {
      await returnIterator();
    } catch (_) {
      // Preserve the original read error.
    }
  }

  function consumeLine(raw) {
    line += 1;

    if (raw.endsWith("\r")) {
      raw = raw.slice(0, -1);
    }

    if (raw.trim() === "") {
      return null;
    }

    try {
      return {
        line: line - 1,
        ok: true,
        value: JSON.parse(raw)
      };
    } catch (_) {
      return {
        line: line - 1,
        ok: false,
        text: raw
      };
    }
  }

  function consumeAvailable() {
    for (;;) {
      const newline = buffer.indexOf("\n");

      if (newline < 0) {
        return null;
      }

      const raw = buffer.slice(0, newline);
      buffer = buffer.slice(newline + 1);

      const event = consumeLine(raw);
      if (event) {
        return event;
      }
    }
  }

  async function readNext() {
    if (closed || eof) {
      return { done: true, value: undefined };
    }

    const source = await acquireIterator();

    for (;;) {
      const event = consumeAvailable();
      if (event) {
        return { done: false, value: event };
      }

      let result;
      try {
        result = await source.next();
      } catch (error) {
        closed = true;
        await returnIteratorIgnoringErrors();
        throw error;
      }

      if (result.done) {
        eof = true;
        buffer += decoder.decode();

        if (buffer.length > 0) {
          const raw = buffer;
          buffer = "";

          const event = consumeLine(raw);
          if (event) {
            return { done: false, value: event };
          }
        }

        closed = true;
        return { done: true, value: undefined };
      }

      buffer += decoder.decode(result.value, { stream: true });
    }
  }

  async function next() {
    if (pendingNext) {
      return pendingNext;
    }

    pendingNext = readNext();

    try {
      return await pendingNext;
    } finally {
      pendingNext = null;
    }
  }

  async function close() {
    if (closed) {
      return;
    }

    closed = true;

    if (pendingNext) {
      try {
        await pendingNext;
      } catch (_) {
        return;
      }
    }

    if (!eof) {
      await returnIterator();
    }
  }

  return { next, close };
}
